parts.openscad_module:
$fn = 128;

wheel_od      = 80;
wheel_w       = 20;
hub_od        = 20;
bore_d        = 6;
bore_clear    = 0.2;
spoke_count   = 5;
rim_t         = 4;
spoke_w       = 5;
oring_w       = 3.1;
oring_depth   = 1.5;

rim_inner_d = wheel_od - 2 * rim_t;

module spoke_wheel() {
  difference() {
    union() {
      difference() {
        cylinder(h = wheel_w, d = wheel_od, center = true);
        cylinder(h = wheel_w + 2, d = rim_inner_d, center = true);
      }
      cylinder(h = wheel_w, d = hub_od, center = true);
      for (i = [0 : spoke_count - 1])
        rotate([0, 0, 360 * i / spoke_count])
          translate([(hub_od/2 + rim_inner_d/2)/2, 0, 0])
            cube([(rim_inner_d - hub_od)/2, spoke_w, wheel_w - 2], center = true);
    }
    cylinder(h = wheel_w + 2, d = bore_d + bore_clear, center = true, $fn = 64);
    rotate_extrude($fn = 128)
      translate([wheel_od/2 - oring_depth, 0, 0])
        square([oring_depth + 0.5, oring_w], center = true);
  }
}

spoke_wheel();
